const INLINE_PREVIEW_MIMES = new Set([
  'application/pdf',
  'image/png',
  'image/jpeg',
  'image/jpg',
  'image/webp'
]);

function normalizeMimeType(value) {
  return String(value || '')
    .split(';')[0]
    .trim()
    .toLowerCase();
}

function parseAttachmentsForRow(row) {
  if (!row) return [];
  try {
    const parsed = JSON.parse(row.attachments_json || '[]');
    return Array.isArray(parsed) ? parsed : [];
  } catch (err) {
    console.warn('[InboundEmail] Invalid attachments JSON', err?.message || err);
    return [];
  }
}

function parseEmailAddress(fromHeader = '') {
  const hint = String(fromHeader || '').trim();
  if (!hint) return '';
  const match = hint.match(/<([^>]+)>/);
  const raw = match ? match[1] : hint;
  return raw.replace(/^"+|"+$/g, '').trim();
}

function normalizeMailboxRole(role = '') {
  return String(role || '').trim().toLowerCase();
}

function isMailboxAdminRole(role = '') {
  return ['admin', 'school_admin'].includes(normalizeMailboxRole(role));
}

function isMailboxStudentRole(role = '') {
  return normalizeMailboxRole(role) === 'student';
}

function normalizeMailboxFolder(folder = '') {
  return String(folder || '').trim().toLowerCase() === 'trash' ? 'trash' : 'inbox';
}

function getMailboxViewer(user) {
  const role = normalizeMailboxRole(user?.role || user?.userRole || '');
  const userId = String(user?.id || user?.sub || '').trim();
  const workspaceId = String(user?.workspaceId || user?.workspace_id || '').trim();
  const isAdmin = isMailboxAdminRole(role);
  const isStudent = isMailboxStudentRole(role);
  return {
    userId,
    workspaceId,
    role,
    isAdmin,
    isStudent,
    canAccess: Boolean(userId && workspaceId && (isAdmin || isStudent))
  };
}

function mailboxTypeSql(alias = '') {
  return `COALESCE(NULLIF(${alias}mailbox_type, ''), 'workspace')`;
}

function mailboxVisibilitySql(alias = '') {
  return `COALESCE(NULLIF(${alias}visibility_scope, ''), 'workspace')`;
}

function mailboxOwnerSql(alias = '') {
  return `COALESCE(NULLIF(${alias}recipient_user_id, ''), NULLIF(${alias}mailbox_owner_user_id, ''), '')`;
}

function buildMailboxWhereClause(viewer, { alias = '', folder = null, ids = null, emailId = null } = {}) {
  if (!viewer?.canAccess) {
    return { where: '1 = 0', params: [] };
  }

  const conditions = [];
  const params = [];

  if (folder !== null) {
    conditions.push(`${alias}folder = ?`);
    params.push(normalizeMailboxFolder(folder));
  }
  if (emailId !== null && emailId !== undefined) {
    conditions.push(`${alias}id = ?`);
    params.push(emailId);
  }
  if (Array.isArray(ids) && ids.length) {
    conditions.push(`${alias}id IN (${ids.map(() => '?').join(',')})`);
    params.push(...ids);
  }

  conditions.push(`${alias}workspace_id = ?`);
  params.push(viewer.workspaceId);

  if (viewer.isAdmin) {
    conditions.push(`${mailboxTypeSql(alias)} = 'workspace'`);
    conditions.push(`${mailboxVisibilitySql(alias)} = 'workspace'`);
  } else {
    conditions.push(`${mailboxTypeSql(alias)} = 'user'`);
    conditions.push(`${mailboxVisibilitySql(alias)} = 'user'`);
    conditions.push(`${mailboxOwnerSql(alias)} = ?`);
    params.push(viewer.userId);
  }

  return {
    where: conditions.join(' AND '),
    params
  };
}

function findAccessibleMailboxRow(viewer, emailId) {
  const parsedEmailId = Number.parseInt(String(emailId || '').trim(), 10);
  if (!Number.isFinite(parsedEmailId)) return null;
  const { where, params } = buildMailboxWhereClause(viewer, { emailId: parsedEmailId });
  return db.prepare(`SELECT * FROM inbound_emails WHERE ${where} LIMIT 1`).get(...params) || null;
}

function buildQuotedText(original = {}) {
  const dt = original.received_at
    ? new Date(original.received_at).toLocaleString()
    : '';
  const from = String(original.sender || '').trim();
  const subj = String(original.subject || '').trim() || '(no subject)';
  const body = String(original.text_body || '').trim();
  const quoted = body
    ? body
        .split('\n')
        .map((line) => `> ${line}`)
        .join('\n')
    : '';
  return `\n\nOn ${dt || 'Unknown Date'}, ${from || 'Sender'} wrote:\nSubject: ${subj}\n\n${quoted}\n`;
}

function buildReplyHtml(replyText = '', original = {}) {
  const dt = original.received_at
    ? new Date(original.received_at).toLocaleString()
    : 'Unknown Date';
  const from = String(original.sender || '').trim() || 'Sender';
  const subj = String(original.subject || '').trim() || '(no subject)';
  const originalBody = escapeHtml(String(original.text_body || '').trim()).replace(/\n/g, '<br>');
  const replyBody = escapeHtml(String(replyText || '').trim()).replace(/\n/g, '<br>');
  return `
    <div style="white-space:normal;">
      <div style="white-space:pre-wrap;">${replyBody}</div>
      <div style="margin-top:16px;padding-top:16px;border-top:1px solid #dbe2ea;color:#5f6368;font-size:13px;">
        <div><strong>On ${escapeHtml(dt)}, ${escapeHtml(from)} wrote:</strong></div>
        <div style="margin-top:4px;"><strong>Subject:</strong> ${escapeHtml(subj)}</div>
        <div style="margin-top:12px;white-space:pre-wrap;">${originalBody}</div>
      </div>
    </div>
  `.trim();
}

const transporter =
  ENV.IONOS_SMTP_HOST && ENV.IONOS_SMTP_USER && ENV.IONOS_SMTP_PASS
    ? nodemailer.createTransport({
        host: ENV.IONOS_SMTP_HOST,
        port: Number(ENV.IONOS_SMTP_PORT),
        secure: ENV.IONOS_SMTP_SECURE,
        auth: {
          user: ENV.IONOS_SMTP_USER,
          pass: ENV.IONOS_SMTP_PASS
        }
      })
    : null;

if (transporter) {
  transporter.verify((err) => {
    if (err) {
      logEvent('warn', '[SMTP] verify failed', { error: safeSerializeError(err) });
    } else {
      logEvent('info', '[SMTP] verify OK');
    }
  });
} else {
  logEvent('warn', '[SMTP] inbound reply transport disabled; IONOS SMTP settings are incomplete.');
}

function findInboxAttachment(emailId, attachmentId) {
  if (!emailId || !attachmentId) return null;
  const row = db
    .prepare('SELECT attachments_json FROM inbound_emails WHERE id = ?')
    .get(emailId);
  if (!row) return null;
  const attachments = parseAttachmentsForRow(row);
  const attachment = attachments.find((item) => String(item.id || '') === attachmentId);
  if (!attachment) return null;
  return { row, attachment };
}

function resolveAttachmentFilePath(storedName) {
  if (!storedName) return null;
  return resolveSafePath(ATTACHMENTS_DIR, storedName);
}

function streamAttachmentResponse(res, filePath, attachment, disposition = 'attachment') {
  if (!filePath || !attachment) return false;
  const filename = normalizeUploadOriginalName(attachment.filename || 'attachment', 'attachment');
  const mimeType = normalizeMimeType(attachment.contentType || 'application/octet-stream');
  const safeDisposition = disposition === 'inline' && isSafeInlineUploadMime(mimeType) ? 'inline' : 'attachment';
  res.setHeader('Content-Type', mimeType || 'application/octet-stream');
  res.setHeader('Content-Disposition', `${safeDisposition}; ${contentDispositionFilename(filename)}`);
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('Cache-Control', 'private, max-age=60');
  const stream = fs.createReadStream(filePath);
  stream.on('error', (streamErr) => {
    console.error('[InboundEmail] Attachment stream failed', streamErr?.message || streamErr);
    if (!res.headersSent) {
      res.status(500).send('Unable to serve attachment');
    }
  });
  stream.pipe(res);
  return true;
}

// WAL is best for concurrent reads/writes
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');
db.pragma('busy_timeout = 5000');

async function backupDatabase(label = 'backup') {
  ensureDir(BACKUP_DIR);
  const safeLabel = String(label || 'backup').toLowerCase().replace(/[^a-z0-9_-]+/g, '-');
  const backupPath = path.join(BACKUP_DIR, `studiestalk-${safeLabel}-${Date.now()}.db`);
  if (typeof db.backup === 'function') {
    await db.backup(backupPath);
  } else {
    db.pragma('wal_checkpoint(PASSIVE)');
    fs.copyFileSync(DB_PATH, backupPath);
  }
  return backupPath;
}

function scheduleDatabaseBackups() {
  const hours = Number(ENV.DB_BACKUP_INTERVAL_HOURS);
  if (!Number.isFinite(hours) || hours <= 0) return;
  const timer = setInterval(() => {
    backupDatabase('scheduled')
      .then((backupPath) => console.log(`[Backup] Created ${backupPath}`))
      .catch((err) => console.error('[Backup] Scheduled backup failed', err));
  }, hours * 60 * 60 * 1000);
  if (typeof timer.unref === 'function') timer.unref();
}

function backfillUserPhoneColumn() {
  if (!hasColumn('users', 'phone')) return;
  db.prepare(`
    UPDATE users
    SET phone = TRIM(
      COALESCE(NULLIF(phone_country, ''), '') ||
      CASE
        WHEN COALESCE(NULLIF(phone_country, ''), '') != '' AND COALESCE(NULLIF(phone_number, ''), '') != '' THEN ' '
        ELSE ''
      END ||
      COALESCE(NULLIF(phone_number, ''), '')
    )
    WHERE COALESCE(NULLIF(phone, ''), '') = ''
      AND (COALESCE(NULLIF(phone_country, ''), '') != '' OR COALESCE(NULLIF(phone_number, ''), '') != '')
  `).run();
}

function markUsersPhoneVerified(phone) {
  if (!hasColumn('users', 'phone_verified')) {
    return { matched: 0, updated: 0, skipped: 'phone_verified_missing' };
  }
  const normalizedPhone = normalizePhoneValue(phone);
  if (!normalizedPhone) {
    return { matched: 0, updated: 0, skipped: 'missing_phone' };
  }
  const matches = findUsersByPhoneForVerification(normalizedPhone);
  if (!matches.length) {
    return { matched: 0, updated: 0, skipped: 'no_matching_user' };
  }
  if (matches.length > 1) {
    return {
      matched: matches.length,
      updated: 0,
      skipped: 'duplicate_phone_matches',
      userIds: matches.map((row) => row.id)
    };
  }
  const matchedUser = matches[0];
  const result = db
    .prepare(
      `UPDATE users
       SET phone = ?,
           phone_verified = 1
       WHERE id = ?`
    )
    .run(normalizedPhone, matchedUser.id);
  return {
    matched: 1,
    updated: result.changes || 0,
    userId: matchedUser.id,
    phone: normalizedPhone
  };
}

function safeAlter(sql) {
  try {
    db.exec(sql);
  } catch (_err) {
    // ignore if column already exists
  }
}

function hasColumn(table, column) {
  try {
    const cols = db.prepare(`PRAGMA table_info(${table})`).all();
    return cols.some((c) => String(c.name || "") === column);
  } catch (_err) {
    return false;
  }
}

function secId(prefix = 'sec') {
  return `${prefix}_${crypto.randomBytes(16).toString('hex')}`;
}

// Auth/session migration boundary: security-event writes now flow through the
// auth repository so route handlers stop owning table-level persistence.
async function logSecurityEvent({
  workspaceId = null,
  actorUserId = null,
  targetUserId = null,
  type,
  severity = 'info',
  ip = null,
  userAgent = null,
  payload = null
}) {
  try {
    await authRepository.writeSecurityEvent({
      id: secId('evt'),
      createdAt: Date.now(),
      workspaceId,
      actorUserId,
      targetUserId,
      type,
      severity,
      ip,
      userAgent,
      payload: payload ? JSON.stringify(payload) : null
    });
  } catch (e) {
    console.warn('logSecurityEvent failed', e);
  }
}

// Auth/session migration boundary: login-attempt writes now flow through the
// auth repository instead of reaching the auth tables directly.
async function logLoginAttempt({ identifier, success, userId = null, workspaceId = null, ip = null, userAgent = null }) {
  try {
    await authRepository.writeLoginAttempt({
      id: secId('la'),
      createdAt: Date.now(),
      identifier: String(identifier || ''),
      success: !!success,
      userId,
      workspaceId,
      ip,
      userAgent
    });
  } catch (e) {
    console.warn('logLoginAttempt failed', e);
  }
}

function isBlockedIp(ip) {
  if (!ip) return false;
  const row = db.prepare(`SELECT ip FROM ip_blocklist WHERE ip = ?`).get(ip);
  return !!row;
}
