app.post('/api/register/otp/send', strictLimiter, async (req, res) => {
  const email = normalizeRegistrationEmail(req.body?.email);
  if (!email) {
    return res.status(400).json({ error: 'A valid email address is required.' });
  }
  const code = generateOtpCode();
  const expiresAt = Date.now() + 5 * 60 * 1000;
  try {
    await registrationRepository.upsertOtp({ email, code, expiresAt, createdAt: nowMs() });
    const session = await getRegistrationSession(req, res);
    if (session?.sessionId) {
      await updateRegistrationSessionRecord(session.sessionId, {
        email,
        email_verified: 0,
        otp_sent_at: nowMs()
      });
    }
    await sendRegistrationOtpEmail(email, code);
    return res.json({ ok: true, expiresAt });
  } catch (error) {
    console.error('Failed to send registration OTP', { email }, error);
    return res.status(500).json({
      error: 'Unable to send the OTP right now. Please try again shortly.'
    });
  }
});

app.post('/api/register/otp/verify', strictLimiter, async (req, res) => {
  const email = normalizeRegistrationEmail(req.body?.email);
  const code = String(req.body?.code || '').trim();
  if (!email || !code) {
    return res.status(400).json({ error: 'Email and OTP code are required.' });
  }
  const row = await registrationRepository.getOtp(email);
  if (!row) {
    return res.status(400).json({ error: 'OTP code is incorrect or has expired.' });
  }
  if (row.expires_at < Date.now()) {
    await registrationRepository.deleteOtp(email);
    return res.status(400).json({ error: 'OTP code is incorrect or has expired.' });
  }
  if (row.code !== code) {
    return res.status(400).json({ error: 'OTP code is incorrect or has expired.' });
  }
  await registrationRepository.deleteOtp(email);
  const session = await setRegistrationEmailVerified(req, res, email);
  return res.json({
    ok: true,
    email_verified: true,
    session: session || null
  });
});

app.post('/api/register/mobile-otp/send', strictLimiter, async (req, res) => {
  try {
    const phone = normalizePhoneValue(req.body?.phone);
    const channel = req.body?.channel === 'call' ? 'call' : 'sms';

    if (!phone) {
      return res.status(400).json({ error: 'phone is required (E.164 format)' });
    }
    const session = await getRegistrationSession(req, res);
    if (session?.sessionId) {
      const currentPhone = normalizePhoneValue(session.phone);
      await updateRegistrationSessionRecord(session.sessionId, {
        phone,
        mobile_verified: currentPhone && currentPhone === phone ? session.mobile_verified : 0
      });
    }
    if (!twilioClient || !twilioVerifyServiceSid) {
      try {
        const payload = await callMobileOtpProxy('/otp/start', { phone, channel });
        return res.json({ ok: true, status: payload?.status });
      } catch (err) {
        console.error('Mobile OTP proxy send failed', err);
        return res.status(500).json({ error: err.message });
      }
    }

    const v = await twilioClient.verify.v2
      .services(twilioVerifyServiceSid)
      .verifications.create({ to: phone, channel });

    return res.json({ ok: true, status: v.status });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

app.post('/api/register/mobile-otp/verify', strictLimiter, async (req, res) => {
  try {
    const phone = normalizePhoneValue(req.body?.phone);
    const code = String(req.body?.code || '').trim();

    if (!phone || !code) {
      return res.status(400).json({ error: 'phone and code are required' });
    }
    if (!twilioClient || !twilioVerifyServiceSid) {
      try {
        const payload = await callMobileOtpProxy('/otp/check', { phone, code });
        if (!payload?.valid) {
          return res.status(400).json({ error: 'Invalid or expired OTP.' });
        }
        const session = await setRegistrationMobileVerified(req, res, phone);
        const userMatch = markUsersPhoneVerified(phone);
        return res.json({
          ok: true,
          status: payload?.status,
          mobile_verified: true,
          session: session || null,
          matched_users: Number(userMatch?.matched || 0),
          updated_users: Number(userMatch?.updated || 0)
        });
      } catch (err) {
        console.error('Mobile OTP proxy verify failed', err);
        return res.status(500).json({ error: err.message });
      }
    }

    const check = await twilioClient.verify.v2
      .services(twilioVerifyServiceSid)
      .verificationChecks.create({ to: phone, code });

    const valid = check.status === 'approved';
    if (!valid) {
      return res.status(400).json({ error: 'Invalid or expired OTP.' });
    }

    const session = await setRegistrationMobileVerified(req, res, phone);
    const userMatch = markUsersPhoneVerified(phone);
    return res.json({
      ok: true,
      status: check.status,
      mobile_verified: true,
      session: session || null,
      matched_users: Number(userMatch?.matched || 0),
      updated_users: Number(userMatch?.updated || 0)
    });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

