function runFfmpeg(args, { strict = false } = {}) {
  return new Promise((resolve, reject) => {
    if (!FFMPEG_CMD) {
      const err = new Error('ffmpeg not available');
      if (strict) return reject(err);
      return resolve({ skipped: true, reason: 'ffmpeg not available' });
    }

    const p = spawn(FFMPEG_CMD, args, { stdio: ['ignore', 'pipe', 'pipe'] });
    let stderr = '';
    let settled = false;

    const finishResolve = (value) => {
      if (settled) return;
      settled = true;
      resolve(value);
    };

    const finishReject = (error) => {
      if (settled) return;
      settled = true;
      reject(error);
    };

    p.stderr.on('data', (d) => (stderr += d.toString()));
    p.on('error', (err) => {
      if (strict) return finishReject(err);
      console.warn('[ffmpeg] conversion error', err.message);
      finishResolve({ ok: false, failed: true, details: err.message });
    });
    p.on('close', (code) => {
      if (code === 0) {
        return finishResolve({ ok: true });
      }
      const err = new Error(`ffmpeg failed (code ${code})`);
      err.details = stderr.slice(-4000);
      if (strict) return finishReject(err);
      console.warn('[ffmpeg] conversion failed:', err.details || err.message);
      finishResolve({ ok: false, failed: true, details: err.details });
    });
  });
}

async function convertIfWebm(filePath, originalName, mimeType) {
  const lowerName = (originalName || '').toLowerCase();
  const isWebm =
    (mimeType && mimeType.includes('webm')) ||
    lowerName.endsWith('.webm') ||
    filePath.toLowerCase().endsWith('.webm');

  if (!isWebm) {
    return { outPath: filePath, outMime: mimeType || 'application/octet-stream' };
  }

  const isAudioOnly =
    (mimeType || '').startsWith('audio/') || /audio/i.test(lowerName);

  if (!FFMPEG_CMD) {
    return { outPath: filePath, outMime: mimeType || 'application/octet-stream' };
  }

  const strictMode = isStrict(process.env);

  try {
    if (isAudioOnly) {
      const outPath = filePath.replace(/\.webm$/i, '') + '.m4a';
      const result = await runFfmpeg(
        [
          '-y',
          '-i', filePath,
          '-vn',
          '-c:a', 'aac',
          '-b:a', '128k',
          '-movflags', '+faststart',
          outPath
        ],
        { strict: strictMode }
      );
      if (!result.ok) {
        return { outPath: filePath, outMime: mimeType || 'application/octet-stream' };
      }
      return { outPath, outMime: 'audio/mp4' };
    }

    const outPath = filePath.replace(/\.webm$/i, '') + '.mp4';
    const result = await runFfmpeg(
      [
        '-y',
        '-i', filePath,
        '-c:v', 'libx264',
        '-pix_fmt', 'yuv420p',
        '-preset', 'veryfast',
        '-movflags', '+faststart',
        '-c:a', 'aac',
        '-b:a', '128k',
        outPath
      ],
      { strict: strictMode }
    );
    if (!result.ok) {
      return { outPath: filePath, outMime: mimeType || 'application/octet-stream' };
    }
    return { outPath, outMime: 'video/mp4' };
  } catch (err) {
    if (strictMode) throw err;
    console.warn('ffmpeg conversion failed, returning original file', err && err.message);
    return { outPath: filePath, outMime: mimeType || 'application/octet-stream' };
  }
}

app.post('/api/uploads', (req, res) => {
  ensureDir(UPLOADS_DIR);
  upload.array('files', 50)(req, res, async (uploadErr) => {
    if (uploadErr) {
      const isMulterErr = uploadErr instanceof multer.MulterError;
      const isValidationErr = !isMulterErr && uploadErr instanceof Error;
      console.error('Upload middleware failed:', uploadErr);
      const statusCode = uploadErr?.code === 'LIMIT_FILE_SIZE'
        ? 400
        : Number(uploadErr?.statusCode || (isMulterErr || isValidationErr ? 400 : 500));
      return res.status(statusCode).json({
        error:
          uploadErr?.code === 'LIMIT_FILE_SIZE'
            ? `File too large. Maximum size is ${Math.floor(UPLOAD_MAX_FILE_BYTES / (1024 * 1024))} MB.`
            : uploadErr?.message || 'Upload failed'
      });
    }

    try {
      const files = Array.isArray(req.files) ? req.files : [];
      if (!files.length) {
        return res.status(400).json({ error: 'No files received' });
      }
      const storageRequester = getEffectiveRequestUser(req);
      const requesterWorkspaceId = String(storageRequester?.workspaceId || '').trim() || 'default';
      const requesterUserId = String(storageRequester?.userId || '').trim() || null;
      const requestedChannelId = String(req.body?.channelId || '').trim() || null;
      let stagingChannelId = null;
      if (requestedChannelId) {
        const channelRow = db.prepare(`
          SELECT id, workspace_id AS workspaceId
          FROM channels
          WHERE id = ?
          LIMIT 1
        `).get(requestedChannelId);
        if (!channelRow) {
          return res.status(400).json({ error: 'Invalid upload channel' });
        }
        if (String(channelRow.workspaceId || '').trim() !== requesterWorkspaceId) {
          return tenantForbidden(res);
        }
        stagingChannelId = String(channelRow.id || '').trim() || null;
      }

      const out = [];

      for (const f of files) {
        if (!f?.path || !fs.existsSync(f.path)) {
          throw new Error(`Uploaded file missing on disk: ${f?.originalname || 'unknown file'}`);
        }

        const absIn = f.path;
        const { outPath, outMime } = await convertIfWebm(absIn, f.originalname, f.mimetype);

        if (!outPath || !fs.existsSync(outPath)) {
          throw new Error(`Processed file missing on disk: ${f.originalname || path.basename(absIn)}`);
        }

        if (outPath !== absIn) {
          try {
            fs.unlinkSync(absIn);
          } catch (_e) {
            /* ignore */
          }
        }

        const stored = await fileStorageService.storeFromFile({
          inputPath: outPath,
          workspaceId: requesterWorkspaceId,
          originalName: f.originalname,
          mimeType: outMime || f.mimetype || 'application/octet-stream',
          permissions: 'workspace_private'
        });
        await fs.promises.unlink(outPath).catch(() => null);

        try {
          registerManagedUploadStagingRow({
            workspaceId: requesterWorkspaceId,
            uploaderId: requesterUserId,
            channelId: stagingChannelId,
            stored,
            purpose: 'upload_temp'
          });
        } catch (registryErr) {
          await cleanupManagedObjectIfSafe(stored);
          throw registryErr;
        }

        out.push({
          url: stored.url,
          originalName: stored.originalName,
          size: stored.sizeBytes,
          mimeType: stored.mimeType,
          storageKey: stored.storageKey,
          checksum: stored.checksum,
          storageProvider: stored.storageProvider,
          storageMode: stored.storageMode,
          encryptionKeyId: stored.encryptionKeyId || '',
          encryptionIv: stored.encryptionIv || '',
          encryptionTag: stored.encryptionTag || '',
          permissions: stored.permissions
        });
      }

      res.json({ files: out });
    } catch (err) {
      console.error('Upload/convert failed:', err);
      res.status(Number(err?.statusCode || 500)).json({ error: err?.message || 'Upload failed' });
    }
  });
});

