app.post('/api/admin/school-requests/:id/create-workspace', async (req, res) => {
  const user = requireSuperAdmin(req, res);
  if (!user) return;

  const id = req.params.id;
  const row = await schoolRequestRepository.getRegistrationReviewRequestById(id);
  if (!row) return res.status(404).json({ error: 'Request not found' });

  if (String(row.status || '').toLowerCase() !== 'approved') {
    return res.status(400).json({ error: 'Request must be approved first' });
  }

  const payload = safeJsonParse(row.payload, {});
  const form = payload?.form || payload || {};
  const email = String(row.email || form?.schoolEmail || form?.adminEmail || '').trim().toLowerCase();
  if (!email) {
    return res.status(400).json({ error: 'Admin email missing' });
  }

  const schoolName = String(
    form?.schoolName || form?.workspaceName || form?.school || 'New School'
  ).trim();
  let workspaceId = String(
    form?.workspaceSlug || form?.workspace_id || form?.workspace || form?.slug || ''
  )
    .trim()
    .toLowerCase();

  if (!workspaceId) {
    workspaceId = schoolName
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 40);
  }
  if (!workspaceId) {
    workspaceId = `school-${Date.now()}`;
  }

  if (await workspaceRepository.workspaceExists(workspaceId)) {
    return res.status(409).json({ error: 'Workspace already exists', workspaceId });
  }

  const schoolCode = String(form?.schoolCode || form?.school_code || '').trim() || null;
  const now = new Date(nowMs()).toISOString();
  const workspaceName = schoolName || `School ${workspaceId}`;

  const contactName = String(
    form?.contactPerson || form?.contact_name || form?.adminName || 'School Admin'
  ).trim();
  const [firstName = 'Admin', ...rest] = contactName.split(' ').filter(Boolean);
  const lastName = rest.join(' ') || 'Admin';
  const username = await userRepository.generateUsername(workspaceId, firstName, lastName);
  const tempPassword = (Math.random().toString(36).slice(2, 10) + 'A9!').slice(0, 10);
  const passwordHash = await hashPassword(tempPassword);
  const tempLoginStartedAt = Date.now();

  const workspaceBootstrap = await workspaceRepository.createApprovedWorkspaceWithAdmin({
    workspace: {
      id: workspaceId,
      name: workspaceName,
      schoolCode,
      adminEmail: email,
      approvedAt: now,
      approvedBy: user.id,
      createdAt: now
    },
    admin: {
      id: generateId('u'),
      firstName,
      lastName,
      name: contactName,
      username,
      email,
      passwordHash,
      tempLoginStartedAt
    },
    defaultChannels: [
      { name: 'general', category: 'classes', topic: 'Welcome to your new workspace' },
      { name: 'announcements', category: 'classes', topic: 'School-wide announcements' },
      { name: 'Conversation Club', category: 'clubs', topic: 'Weekly conversation practice' },
      { name: 'Speaking Club', category: 'clubs', topic: 'Fluency and speaking drills' },
      { name: 'Culture Exchange', category: 'clubs', topic: 'Share culture and language tips' },
      { name: 'Announcements', category: 'tools', topic: 'Important school updates' },
      { name: 'Learning Materials', category: 'tools', topic: 'Study guides and resources' },
      { name: 'Speaking Practice', category: 'tools', topic: 'Speaking drills and prompts' },
      { name: 'Listening Practice', category: 'tools', topic: 'Listening activities and audio' },
      { name: 'Wordmeaning', category: 'tools', topic: 'Word meaning discussion and usage' },
      { name: 'Schedule', category: 'tools', topic: 'Class schedule and timetable' },
      { name: 'Exam Registration', category: 'tools', topic: 'Exam registration details' },
      { name: 'B1 Mock Test', category: 'exams', topic: 'Mock exam practice' },
      { name: 'Placement Test', category: 'exams', topic: 'Placement assessment' },
      { name: 'Final Exam – March', category: 'exams', topic: 'Final exam session' },
      { id: `teachers-${workspaceId}`, name: 'Teachers', category: 'teachers', topic: 'Teachers-only staff room' }
    ]
  });
  const adminId = workspaceBootstrap.adminId;
  const existingUser = workspaceBootstrap.existingUser;

  await billingRepository.ensureWorkspaceBilling({ workspaceId, billingEmail: email });
  await onboardingRepository.ensureWorkspaceOnboarding({
    workspaceId,
    requestId: id,
    createdBy: user.id,
    now
  });

  let emailSent = false;
  let emailError = null;
  let emailProviderUsed = providerName || 'provider';
  if (!tempPassword) {
    emailProviderUsed = null;
  }
  if (tempPassword) {
    try {
      const schoolNameSafe = String(schoolName || 'StudisNest').trim();
      const loginUrl = `${req.protocol}://${req.get('host')}/`;
      const subject = `Your ${schoolNameSafe} admin account is ready`;
      const text = `Hello,\n\nYour school request has been approved and your admin account is ready.\n\nLogin email: ${row.email}\nTemporary password: ${tempPassword}\n\nLogin here: ${loginUrl}\n\nPlease change your password after your first login.\n\n— StudisNest`;
      const html = `
      <div style="font-family:Inter,system-ui,Arial;line-height:1.5;color:#0f172a">
        <h2 style="margin:0 0 12px 0;">Your admin account is ready ✅</h2>

        <p style="margin:0 0 14px 0;">
          Your school request has been approved and your workspace has been created.
        </p>

        <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:12px;padding:14px;margin:14px 0;">
          <div><b>School:</b> ${escapeHtml(schoolNameSafe)}</div>
          <div><b>Workspace:</b> ${escapeHtml(workspaceId)}</div>
          <div><b>Login email:</b> ${escapeHtml(row.email)}</div>
          <div style="margin-top:10px;">
            <b>Temporary password:</b>
            <span style="display:inline-block;background:#fff;border:1px solid #e2e8f0;padding:6px 10px;border-radius:10px;font-family:ui-monospace, SFMono-Regular, Menlo, monospace;">
              ${escapeHtml(tempPassword)}
            </span>
          </div>
        </div>

        <p style="margin:0 0 14px 0;">
          <a href="${loginUrl}" style="display:inline-block;background:#2563eb;color:#fff;text-decoration:none;padding:10px 14px;border-radius:10px;font-weight:700;">
            Open login
          </a>
        </p>

        <p style="margin:0;color:#475569;font-size:13px;">
          For security, please change your password after your first login.
        </p>
      </div>`;
      await sendPlatformEmail({ to: row.email, subject, text, html });
      emailSent = true;
    } catch (e) {
      console.error('Failed to send temp password email:', e);
      emailError = String(e?.message || e);
    }
  }

  legacyAuditLog({
    workspaceId,
    actor: user.id,
    action: 'school_request.create_workspace',
    target: id,
    payload: { workspaceId, email, adminId }
  });

  res.json({
    ok: true,
    workspaceId,
    adminEmail: email,
    tempPassword: existingUser ? null : tempPassword,
    emailSent,
    emailError,
    emailProvider: emailProviderUsed,
    onboarding: await onboardingRepository.getWorkspaceOnboarding(workspaceId)
  });
});

