app.get('/api/admin/inbox', requireAccessToken, async (req, res) => {
  const viewer = getMailboxViewer(req.auth);
  if (!viewer.canAccess) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const shouldSync = String(req.query.sync || '0') === '1';
  const folder = normalizeMailboxFolder(req.query.folder || 'inbox');
  if (shouldSync && viewer.isAdmin && inboundEmailService.isConfigured()) {
    try {
      await inboundEmailService.syncInboundEmails(db);
    } catch (err) {
      console.error('[InboundEmail] Failed to sync inbox before listing', err?.message || err);
    }
  }

  const { where, params } = buildMailboxWhereClause(viewer, { folder });
  const rows = db
    .prepare(`
      SELECT *
      FROM inbound_emails
      WHERE ${where}
      ORDER BY received_at DESC
    `)
    .all(...params);

  const repliesStmt = db.prepare(`
    SELECT id, body, created_at
    FROM email_replies
    WHERE inbound_email_id = ?
    ORDER BY created_at ASC
  `);

  const inboxRows = rows.map((row) => {
    const attachments = parseAttachmentsForRow(row);
    const safeAttachments = attachments
      .filter(Boolean)
      .map((att) => ({
        id: String(att.id || '').trim(),
        filename: String(att.filename || 'attachment'),
        size: Number(att.size || 0),
        contentType: String(att.contentType || ''),
        inline: Boolean(att.inline),
        contentId: String(att.contentId || '')
      }))
      .filter((att) => att.id);

    const { attachments_json, ...rest } = row;
    return {
      ...rest,
      replies: (repliesStmt.all(row.id) || []).map((reply) => ({
        id: reply?.id,
        body: reply?.body || '',
        created_at: reply?.created_at || ''
      })),
      attachments: safeAttachments,
      hasAttachments: safeAttachments.length > 0,
      attachmentsCount: safeAttachments.length,
      totalAttachmentBytes: safeAttachments.reduce((sum, att) => sum + (Number(att.size) || 0), 0),
      hasInline: safeAttachments.some((att) => Boolean(att.inline || att.contentId))
    };
  });

  res.json(inboxRows);
});

app.post(
  '/api/admin/inbox/contact-form',
  requireAccessToken,
  express.json(),
  (req, res) => {
    try {
      const viewer = getMailboxViewer(req.auth);
      if (!viewer.isStudent) {
        return res.status(403).json({ error: 'Only students can use the contact form' });
      }

      const student = db
        .prepare(
          `
          SELECT id, workspace_id AS workspaceId, name, first_name, last_name, email, role
          FROM users
          WHERE id = ?
            AND workspace_id = ?
          LIMIT 1
        `
        )
        .get(viewer.userId, viewer.workspaceId);
      if (!student) {
        return res.status(404).json({ error: 'Student account not found' });
      }

      const subject = String(req.body?.subject || '').trim();
      const message = String(req.body?.message || '').trim();
      const messageWords = message ? message.split(/\s+/).filter(Boolean).length : 0;
      if (!subject) {
        return res.status(400).json({ error: 'Subject is required' });
      }
      if (subject.length > 120) {
        return res.status(400).json({ error: 'Subject must be 120 characters or less' });
      }
      if (!message) {
        return res.status(400).json({ error: 'Message is required' });
      }
      if (messageWords > 500) {
        return res.status(400).json({ error: 'Message must be 500 words or less' });
      }

      const adminUser = getWorkspaceAdminMailboxUser(viewer.workspaceId);
      if (!adminUser?.id) {
        return res.status(404).json({ error: 'School admin mailbox was not found' });
      }

      const senderName =
        String(
          student.name ||
            `${student.first_name || ''} ${student.last_name || ''}`.trim() ||
            student.email ||
            'Student'
        ).trim() || 'Student';
      const senderEmail = String(student.email || '').trim();
      const senderLabel = senderEmail ? `${senderName} <${senderEmail}>` : senderName;

      const adminName =
        String(
          adminUser.name ||
            `${adminUser.first_name || ''} ${adminUser.last_name || ''}`.trim() ||
            adminUser.email ||
            'School Admin'
        ).trim() || 'School Admin';
      const adminEmail = String(adminUser.email || '').trim();
      const recipientLabel = adminEmail ? `${adminName} <${adminEmail}>` : adminName;

      db.prepare(
        `
        INSERT INTO inbound_emails (
          workspace_id, message_id, sender, recipient, subject,
          text_body, html_body, in_reply_to, references_header, related_email_log_id,
          folder, attachments_json, received_at, is_read,
          mailbox_type, mailbox_owner_user_id, sender_user_id, recipient_user_id,
          direction, visibility_scope, sender_role
        )
        VALUES (?, ?, ?, ?, ?, ?, ?, '', '', '', 'inbox', '', ?, 0, 'workspace', ?, ?, ?, 'inbound', 'workspace', ?)
      `
      ).run(
        viewer.workspaceId,
        uuid('cform'),
        senderLabel,
        recipientLabel,
        subject,
        message,
        `<div style="white-space:pre-wrap;">${escapeHtml(message)}</div>`,
        new Date().toISOString(),
        adminUser.id,
        student.id,
        adminUser.id,
        normalizeMailboxRole(student.role || 'student')
      );

      res.json({ ok: true });
    } catch (err) {
      console.error('[InboundEmail] Contact form failed', err?.message || err);
      res.status(500).json({ error: 'Failed to send contact form' });
    }
  }
);

function parseInboxBulkIds(body = {}) {
  return Array.isArray(body?.ids)
    ? body.ids
        .map((value) => Number.parseInt(String(value || '').trim(), 10))
        .filter((value) => Number.isFinite(value))
    : [];
}

function deleteInboxRowsForever(rows = []) {
  for (const row of rows) {
    const messageId = String(row?.message_id || '').trim();
    if (messageId) {
      db.prepare(`
        INSERT INTO deleted_inbound_emails (message_id, deleted_at)
        VALUES (?, datetime('now'))
        ON CONFLICT(message_id) DO UPDATE SET deleted_at = datetime('now')
      `).run(messageId);
    }
    const attachments = parseAttachmentsForRow(row);
    for (const attachment of attachments) {
      const filePath = resolveAttachmentFilePath(attachment?.storedName);
      if (!filePath) continue;
      try {
        if (fs.existsSync(filePath)) {
          fs.unlinkSync(filePath);
        }
      } catch (err) {
        console.warn('[InboundEmail] Failed to delete attachment file', filePath, err?.message || err);
      }
    }
  }
}

app.post(
  '/api/admin/inbox/bulk-delete',
  requireAccessToken,
  express.json(),
  async (req, res) => {
    try {
      const viewer = getMailboxViewer(req.auth);
      if (!viewer.canAccess) {
        return res.status(403).json({ error: 'Forbidden' });
      }
      const ids = parseInboxBulkIds(req.body);

      if (!ids.length) {
        return res.status(400).json({ error: 'No inbox emails selected' });
      }

      const scoped = buildMailboxWhereClause(viewer, { folder: 'inbox', ids });
      const selectStmt = db.prepare(
        `SELECT id, message_id, attachments_json FROM inbound_emails WHERE ${scoped.where}`
      );
      const rows = selectStmt.all(...scoped.params);
      if (!rows.length) {
        return res.status(404).json({ error: 'Selected inbox emails were not found' });
      }

      db.prepare(
        `UPDATE inbound_emails SET folder = 'trash' WHERE ${scoped.where}`
      ).run(...scoped.params);

      res.json({ ok: true, deleted: rows.length, movedTo: 'trash' });
    } catch (err) {
      console.error('[InboundEmail] Bulk delete failed', err?.message || err);
      res.status(500).json({ error: 'Failed to delete inbox emails' });
    }
  }
);

