app.post('/api/auth/forgot-password', async (req, res) => {
  try {
    const email = normalizeRegistrationEmail(req.body?.email || req.body?.login);
    if (!email) {
      return res.status(400).json({ error: 'Email is required' });
    }

    const user = await userRepository.findPasswordResetUserByEmail(email);
    if (!user || !user.id || !user.email) {
      return res.json({ ok: true });
    }

    const token = generatePasswordResetToken();
    const tokenHash = sha256(token);
    const createdAt = nowMs();
    const expiresAt = createdAt + PASSWORD_RESET_EXPIRY_HOURS * 60 * 60 * 1000;

    await authRepository.createPasswordReset({
      tokenHash,
      userId: user.id,
      workspaceId: user.workspaceId || null,
      createdAt,
      expiresAt
    });

    try {
      await sendPasswordResetEmail(user, token);
    } catch (emailError) {
      await authRepository.deletePasswordResetByHash(tokenHash);
      throw emailError;
    }

    void logSecurityEvent({
      workspaceId: user.workspaceId || null,
      actorUserId: user.id,
      type: 'auth.password_reset_requested',
      severity: 'info',
      ip: req.ip || null,
      userAgent: req.headers['user-agent'] || null,
      payload: { email }
    });

    return res.json({ ok: true });
  } catch (err) {
    console.error('forgot-password failed:', err);
    return res.status(500).json({ error: 'Could not send reset email' });
  }
});

app.post('/api/auth/reset-password/complete', async (req, res) => {
  try {
    const token = String(req.body?.token || '').trim();
    const password = String(req.body?.password || '').trim();

    if (!token) {
      return res.status(400).json({ error: 'Token is required' });
    }
    if (!password) {
      return res.status(400).json({ error: 'Password is required' });
    }
    const passwordValidationError = getPasswordValidationError(password);
    if (passwordValidationError) {
      await logSecurityEvent({
        workspaceId: null,
        actorUserId: null,
        type: 'security.weak_password_rejected',
        severity: 'warn',
        ip: req.ip || null,
        userAgent: req.headers['user-agent'] || null,
        payload: { route: 'auth.reset_password.complete' }
      });
      return res.status(400).json({ error: passwordValidationError });
    }

    const resetRow = await getResetToken(token);
    if (!resetRow) {
      return res.status(404).json({ error: 'Invalid token' });
    }
    if (resetRow.used) {
      return res.status(400).json({ error: 'This reset link was already used' });
    }
    if (Number(resetRow.expiresAt) < nowMs()) {
      return res.status(400).json({ error: 'Link expired' });
    }

    const user = await userRepository.getPasswordResetUserById(resetRow.userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    const passwordHash = await hashPassword(password);
    const changedAt = new Date().toISOString();
    const revokedAt = nowMs();

    await userRepository.updatePasswordAfterReset({
      userId: user.id,
      passwordHash,
      changedAt,
      historyId: secId('pwh'),
      historyCreatedAt: revokedAt,
      tokenHash: resetRow.tokenHash,
      legacyToken: resetRow.legacyToken || null
    });

    await authRepository.revokeAllRefreshTokensForUser(user.id, revokedAt);

    void logSecurityEvent({
      workspaceId: user.workspaceId || null,
      actorUserId: user.id,
      type: 'security.password_changed',
      severity: 'info',
      ip: req.ip || null,
      userAgent: req.headers['user-agent'] || null,
      payload: { viaReset: true }
    });
    void logSecurityEvent({
      workspaceId: user.workspaceId || null,
      actorUserId: user.id,
      type: 'auth.password_reset_completed',
      severity: 'info',
      ip: req.ip || null,
      userAgent: req.headers['user-agent'] || null,
      payload: { viaReset: true }
    });

    try {
      await sendPasswordChangedEmail(user);
    } catch (emailErr) {
      console.warn('password-changed email failed:', emailErr?.message || emailErr);
    }

    clearAuthCookies(res);
    return res.json({ ok: true });
  } catch (err) {
    console.error('reset-password complete failed:', err);
    return res.status(500).json({ error: 'Could not update password' });
  }
});

app.post('/api/auth/refresh', async (req, res) => {
  const rt = req.cookies?.refresh_token;
  if (!rt) return res.status(401).json({ error: 'Unauthorized' });

  let payload;
  try {
    payload = jwt.verify(rt, JWT_REFRESH_SECRET);
  } catch {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const hash = sha256(rt);
  let row = await authRepository.getActiveRefreshToken({
    id: payload.jti,
    userId: payload.sub,
    tokenHash: hash
  });

  const nowMs = Date.now();
  if (!row) {
    const expiresAt = nowMs + 30 * 24 * 60 * 60 * 1000;
    await authRepository.insertRefreshTokenIfMissing({
      id: payload.jti,
      userId: payload.sub,
      tokenHash: hash,
      createdAt: nowMs,
      issuedAt: nowMs,
      expiresAt,
      ip: req.ip || null,
      userAgent: req.headers['user-agent'] || null
    });
    row = { id: payload.jti };
  } else if (nowMs > Number(row.expires_at)) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  const user = await userRepository.getUserAuthProfile(payload.sub);

  if (!user) return res.status(401).json({ error: 'Unauthorized' });

  const access = signAccessToken({
    id: user.id,
    role: user.role,
    workspaceId: user.workspaceId,
  });
  const ip = req.ip || null;
  const userAgent = req.headers['user-agent'] || null;
  const refresh = signRefreshToken(user);
  const refreshDecoded = jwt.decode(refresh.token);
  const now = Date.now();
  const refreshExpires = Number(refreshDecoded?.exp ? refreshDecoded.exp * 1000 : now + 30 * 86400000);

  await authRepository.revokeAndReplaceRefreshToken({
    existingId: row.id,
    revokedAt: now,
    replacedBy: refresh.jti,
    newToken: {
      id: refresh.jti,
      userId: user.id,
      tokenHash: sha256(refresh.token),
      createdAt: now,
      issuedAt: now,
      expiresAt: refreshExpires,
      ip,
      userAgent
    }
  });

  setAuthCookies(res, access.token, refresh.token);

  logSecurityEvent({
    workspaceId: user.workspaceId || null,
    actorUserId: user.id,
    type: 'auth.refresh',
    severity: 'info',
    ip,
    userAgent,
    payload: { refreshed: true }
  });

  return res.json({ accessToken: access.token });
});

app.post('/api/auth/logout', requireAccessToken, async (req, res) => {
  const refreshToken = req.cookies?.refresh_token || null;
  const accessToken = getAccessTokenFromRequest(req);
  const now = Date.now();

  try {
    if (refreshToken) {
      const refreshPayload = jwt.verify(refreshToken, JWT_REFRESH_SECRET);
      if (refreshPayload?.jti) {
        await authRepository.revokeRefreshToken(refreshPayload.jti, now);
      }
    }
  } catch (_err) {
    // best-effort logout; still clear cookies below
  }

  if (accessToken) {
    const decoded = verifyAccessToken(accessToken);
    if (decoded?.jti) {
      const expiresAt = decoded?.exp ? Number(decoded.exp) * 1000 : now;
      await authRepository.revokeAccessToken({
        jti: decoded.jti,
        userId: decoded.sub || decoded.id || null,
        revokedAt: now,
        expiresAt
      });
    }
  }

  clearAuthCookies(res);
  void logSecurityEvent({
    workspaceId: req.auth?.workspaceId || req.auth?.workspace_id || null,
    actorUserId: req.auth?.sub || req.auth?.id || null,
    type: 'auth.logout',
    severity: 'info',
    ip: req.ip || null,
    userAgent: req.headers['user-agent'] || null,
    payload: { loggedOut: true }
  });
  return res.json({ ok: true });
});

// =========================
// TASK CHANNEL APIs
// =========================
function getAuthContext(req) {
  const u = req.user || req.auth || req.sessionUser || getAuthedUser(req) || {};
  return {
    userId: u.id || u.userId || req.headers['x-user-id'],
    workspaceId: u.workspace_id || u.workspaceId || req.headers['x-workspace-id'],
    role: u.role || u.user_role || u.userRole || ''
  };
}

function mustAuthTask(req, res) {
  const ctx = getAuthContext(req);
  if (!ctx.userId || !ctx.workspaceId) {
    res.status(401).json({ error: 'Unauthorized' });
    return null;
  }
  return ctx;
}

function canAccessTaskChannelByName(role, name) {
  const normalizedRole = String(role || '').trim().toLowerCase();
  const normalizedName = String(name || '').trim().toLowerCase();
  if (normalizedName === 'school task') {
    return normalizedRole === 'school_admin' || normalizedRole === 'super_admin';
  }
  if (normalizedName === 'teachers task') {
    return normalizedRole === 'teacher' || normalizedRole === 'school_admin' || normalizedRole === 'super_admin';
  }
  if (normalizedName === 'student tasks') {
    return ['student', 'teacher', 'school_admin', 'super_admin'].includes(normalizedRole);
  }
  return true;
}

function isTaskChannelName(name) {
  const normalizedName = String(name || '').trim().toLowerCase();
  return normalizedName === 'school task' || normalizedName === 'teachers task' || normalizedName === 'student tasks';
}

function getTaskScopedChannel(workspaceId, channelId) {
  return db
    .prepare(`SELECT id, workspace_id, name, category FROM channels WHERE id = ?`)
    .get(String(channelId || ''));
}

function assertTaskChannelAccess(workspaceId, channelId, role) {
  try {
    const row = getTaskScopedChannel(workspaceId, channelId);
    if (!row) return false;
    if (String(row.workspace_id) !== String(workspaceId)) return false;
    return canAccessTaskChannelByName(role, row.name);
  } catch (_e) {
    return false;
  }
}

async function assertTaskChannelAccessAsync(workspaceId, channelId, role) {
  try {
    const row = await channelRepository.getChannelById(String(channelId || ''));
    if (!row) return false;
    if (String(row.workspaceId || row.workspace_id) !== String(workspaceId)) return false;
    return canAccessTaskChannelByName(role, row.name);
  } catch (_e) {
    return false;
  }
}

function enforceTaskChannelRouteAccess(req, res, channelId) {
  const row = getTaskScopedChannel(null, channelId);
  if (!row) return true;
  if (!isTaskChannelName(row.name)) {
    return true;
  }
  const ctx = getAuthContext(req);
  if (!ctx.userId || !ctx.workspaceId) {
    res.status(401).json({ error: 'Unauthorized' });
    return false;
  }
  if (!assertTaskChannelAccess(ctx.workspaceId, channelId, ctx.role)) {
    res.status(403).json({ error: 'Forbidden' });
    return false;
  }
  return true;
}

function canManageTasks(role) {
  const r = String(role || '').toLowerCase();
  return r === 'teacher' || r === 'school_admin' || r === 'super_admin';
}

function assertChannelInWorkspace(workspaceId, channelId) {
  try {
    const row = db.prepare(`SELECT id, workspace_id FROM channels WHERE id = ?`).get(String(channelId));
    if (!row) return false;
    return String(row.workspace_id) === String(workspaceId);
  } catch (_e) {
    return true;
  }
}

function taskToDto(t) {
  return {
    id: t.id,
    workspaceId: t.workspace_id,
    channelId: t.channel_id,
    title: t.title,
    description: t.description || '',
    status: t.status,
    priority: t.priority,
    dueAt: t.due_at || null,
    completedAt: t.completed_at || null,
    createdBy: t.created_by,
    assignedTo: t.assigned_to || null,
    createdAt: t.created_at,
    updatedAt: t.updated_at
  };
}

function ensureStatus(s) {
  const v = String(s || '').toLowerCase();
  if (['open', 'doing', 'done'].includes(v)) return v;
  return 'open';
}

function ensurePriority(p) {
  const v = String(p || '').toLowerCase();
  if (['low', 'normal', 'high', 'urgent'].includes(v)) return v;
  return 'normal';
}

app.get('/api/tasks', authRequired, async (req, res) => {
  const ctx = mustAuthTask(req, res);
  if (!ctx) return;

  const channelId = String(req.query.channelId || '');
  if (!channelId) return res.status(400).json({ error: 'channelId required' });
  if (!await assertTaskChannelAccessAsync(ctx.workspaceId, channelId, ctx.role)) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const status = String(req.query.status || '').trim().toLowerCase();
  const limit = Math.min(200, Math.max(1, Number(req.query.limit || 50)));
  const includeDone = String(req.query.includeDone || 'true') === 'true';

  try {
    const tasks = await tasksRepository.listTasks({
      workspaceId: ctx.workspaceId,
      channelId,
      status,
      includeDone,
      limit,
      userId: ctx.userId
    });
    res.json({ tasks });
  } catch (err) {
    console.error('[Tasks] List failed', err);
    res.status(500).json({ error: 'Failed to load tasks' });
  }
});

app.post('/api/tasks', authRequired, express.json(), async (req, res) => {
  const ctx = mustAuthTask(req, res);
  if (!ctx) return;
  const role = ctx.role;
  if (!canManageTasks(role)) return res.status(403).json({ error: 'Forbidden' });

  const channelId = String(req.body.channelId || '');
  const title = String(req.body.title || '').trim();
  const description = String(req.body.description || '').trim();
  const status = ensureStatus(req.body.status);
  const priority = ensurePriority(req.body.priority);
  const dueAt = req.body.dueAt ? Number(req.body.dueAt) : null;
  const assignedTo = req.body.assignedTo ? String(req.body.assignedTo) : null;

  if (!channelId) return res.status(400).json({ error: 'channelId required' });
  if (!title) return res.status(400).json({ error: 'title required' });
  if (!await assertTaskChannelAccessAsync(ctx.workspaceId, channelId, ctx.role)) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  try {
    const id = secId('task');
    const now = nowMs();
    const task = await tasksRepository.createTask({
      id,
      workspaceId: ctx.workspaceId,
      channelId,
      title,
      description,
      status,
      priority,
      dueAt: dueAt || null,
      createdBy: ctx.userId,
      assignedTo,
      createdAt: now,
      updatedAt: now,
      completedAt: status === 'done' ? now : null
    });
    res.json({ task });
  } catch (err) {
    console.error('[Tasks] Create failed', err);
    res.status(500).json({ error: 'Failed to create task' });
  }
});

app.patch('/api/tasks/:id', authRequired, express.json(), async (req, res) => {
  const ctx = mustAuthTask(req, res);
  if (!ctx) return;

  const taskId = String(req.params.id || '');
  const existing = await tasksRepository.getTaskById({ taskId, workspaceId: ctx.workspaceId });
  if (!existing) return res.status(404).json({ error: 'Not found' });
  if (!await assertTaskChannelAccessAsync(ctx.workspaceId, existing.channelId, ctx.role)) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const role = ctx.role;
  const canManage = canManageTasks(role);
  const isOwner = String(existing.createdBy) === String(ctx.userId);
  const isAssignee = existing.assignedTo && String(existing.assignedTo) === String(ctx.userId);

  if (!canManage && !(isOwner || isAssignee)) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const patch = {
    title: req.body.title != null ? String(req.body.title).trim() : null,
    description: req.body.description != null ? String(req.body.description).trim() : null,
    status: req.body.status != null ? ensureStatus(req.body.status) : null,
    priority: req.body.priority != null ? ensurePriority(req.body.priority) : null,
    dueAt: req.body.dueAt != null ? (req.body.dueAt ? Number(req.body.dueAt) : null) : undefined,
    assignedTo: req.body.assignedTo != null ? (req.body.assignedTo ? String(req.body.assignedTo) : null) : undefined
  };

  if (!canManage) {
    patch.title = null;
    patch.description = null;
    patch.priority = null;
    patch.dueAt = undefined;
    patch.assignedTo = undefined;
  }

  const now = nowMs();
  const nextStatus = patch.status ?? existing.status;
  const completedAt =
    nextStatus === 'done' ? (existing.completedAt || now) : null;

  try {
    const task = await tasksRepository.updateTask({
      taskId,
      workspaceId: ctx.workspaceId,
      existingTask: existing,
      patch,
      updatedAt: now,
      completedAt
    });
    res.json({ task });
  } catch (err) {
    console.error('[Tasks] Update failed', err);
    res.status(500).json({ error: 'Failed to update task' });
  }
});

