async function resolveLiveBreakoutRoomAccess(req, roomId, { requireManage = false } = {}) {
  const room = getLiveBreakoutRoomById(roomId);
  if (!room) return { ok: false, status: 404 };
  const sessionAccess = await resolveLiveSessionAccess(req, room.session_id, { requireManage });
  if (!sessionAccess.ok) {
    return { ...sessionAccess, room };
  }
  return {
    ok: true,
    user: sessionAccess.user,
    session: sessionAccess.session,
    room
  };
}

function canUserJoinLiveBreakoutRoom(user, session, room) {
  if (!user || !session || !room) return false;
  if (canUserManageSpecificLiveSession(user, session)) {
    return normalizeLiveBreakoutRoomStatus(room.status || '') === 'open';
  }
  if (!canUserConsumeLiveSessionContent(user, session)) return false;
  const participant = getLiveSessionParticipant(session.id, user.id || user.sub);
  const participantStatus = normalizeLiveParticipantStatus(participant?.status || '');
  if (!['approved', 'joined'].includes(participantStatus)) return false;
  if (normalizeLiveBreakoutRoomStatus(room.status || '') !== 'open') return false;
  return Boolean(getLiveBreakoutRoomMember(room.id, user.id || user.sub));
}

function listLiveBreakoutRoomsForViewer(session, viewer) {
  const canManage = canUserManageSpecificLiveSession(viewer, session);
  const rows = listLiveBreakoutRoomRows(session.id);
  return rows
    .map((room) => buildLiveBreakoutRoomForClient(session, room, viewer, { canManage }))
    .filter((room) => canManage || room.self);
}

function createLivePoll({
  session,
  actor,
  type = 'poll',
  question,
  status = 'draft',
  allowMultiple = false,
  anonymousResults = false,
  options = [],
  correctOptionIndex = null
}) {
  const normalizedOptions = options
    .map((text) => String(text || '').trim())
    .filter(Boolean)
    .slice(0, 8);
  if (normalizedOptions.length < 2) {
    const err = new Error('At least two options are required.');
    err.statusCode = 400;
    throw err;
  }
  const trimmedQuestion = String(question || '').trim();
  if (!trimmedQuestion) {
    const err = new Error('Question is required.');
    err.statusCode = 400;
    throw err;
  }
  const pollId = generateId('lpoll');
  const optionRows = normalizedOptions.map((text, index) => ({
    id: generateId('lpopt'),
    text,
    sortOrder: index
  }));
  const correctIdx = Number.isInteger(correctOptionIndex) ? correctOptionIndex : Number(correctOptionIndex);
  const correctOptionId = normalizeLivePollType(type) === 'quiz' && Number.isInteger(correctIdx) && correctIdx >= 0 && correctIdx < optionRows.length
    ? optionRows[correctIdx].id
    : null;
  const now = nowIso();
  const insertTx = db.transaction(() => {
    db.prepare(`
      INSERT INTO live_session_polls (
        id, workspace_id, session_id, created_by_user_id, type, question, status,
        allow_multiple, anonymous_results, correct_option_id, created_at, opened_at, closed_at
      ) VALUES (
        @id, @workspace_id, @session_id, @created_by_user_id, @type, @question, @status,
        @allow_multiple, @anonymous_results, @correct_option_id, @created_at, @opened_at, @closed_at
      )
    `).run({
      id: pollId,
      workspace_id: String(session.workspace_id || session.workspaceId || '').trim() || 'default',
      session_id: String(session.id || '').trim(),
      created_by_user_id: actor?.id || null,
      type: normalizeLivePollType(type),
      question: trimmedQuestion,
      status: normalizeLivePollStatus(status),
      allow_multiple: allowMultiple ? 1 : 0,
      anonymous_results: anonymousResults ? 1 : 0,
      correct_option_id: correctOptionId,
      created_at: now,
      opened_at: normalizeLivePollStatus(status) === 'open' ? now : null,
      closed_at: normalizeLivePollStatus(status) === 'closed' ? now : null
    });
    const optionStmt = db.prepare(`
      INSERT INTO live_session_poll_options (id, poll_id, text, sort_order)
      VALUES (@id, @poll_id, @text, @sort_order)
    `);
    optionRows.forEach((row) => {
      optionStmt.run({
        id: row.id,
        poll_id: pollId,
        text: row.text,
        sort_order: row.sortOrder
      });
    });
  });
  insertTx();
  return getLivePollById(pollId);
}

function updateLivePollStatus(pollId, status) {
  const normalizedStatus = normalizeLivePollStatus(status);
  const now = nowIso();
  db.prepare(`
    UPDATE live_session_polls
    SET status = ?,
        opened_at = CASE WHEN ? = 'open' THEN COALESCE(opened_at, ?) ELSE opened_at END,
        closed_at = CASE WHEN ? = 'closed' THEN ? ELSE closed_at END
    WHERE id = ?
  `).run(normalizedStatus, normalizedStatus, now, normalizedStatus, now, String(pollId || '').trim());
  return getLivePollById(pollId);
}

function buildLiveSessionControlState(session, viewer) {
  const participants = listLiveSessionParticipants(session.id);
  const selfParticipant = viewer?.id ? getLiveSessionParticipant(session.id, viewer.id) : null;
  const recording = getLiveSessionRecording(session.id);
  const canManage = canUserManageSpecificLiveSession(viewer, session);
  const breakoutRooms = listLiveBreakoutRoomsForViewer(session, viewer);
  const pending = participants
    .filter((row) => normalizeLiveParticipantStatus(row.status) === 'pending')
    .map(formatLiveParticipantForClient);
  const raisedHands = participants
    .filter((row) => normalizeLiveHandStatus(row.hand_status) === 'raised')
    .map(formatLiveParticipantForClient);
  const joined = participants
    .filter((row) => normalizeLiveParticipantStatus(row.status) === 'joined')
    .map(formatLiveParticipantForClient);
  const self = selfParticipant ? formatLiveParticipantForClient(selfParticipant) : null;
  const recordingEnabled = Number(recording?.recording_enabled || 0) === 1;
  const consentRequired = Number(recording?.consent_required === 0 ? 0 : 1) === 1;
  const studentPlaybackAllowed = Number(recording?.student_playback_allowed || 0) === 1;
  const consentPending = participants
    .filter((row) => normalizeLiveParticipantStatus(row.status) !== 'denied')
    .filter((row) => !LIVE_RECORDING_MANAGER_ROLES.has(String(row.role || '').trim().toLowerCase()))
    .filter((row) => !normalizeLiveRecordingConsent(row.recording_consent))
    .map(formatLiveParticipantForClient);
  const recordingState = {
    enabled: recordingEnabled,
    startedAt: recording?.recording_started_at || null,
    startedBy: recording?.recording_started_by || null,
    consentRequired,
    consentPendingCount: recordingEnabled ? consentPending.length : 0,
    studentPlaybackAllowed
  };
  if (!canManage) {
    return {
      self,
      recording: {
        ...recordingState,
        selfConsentRequired: !!(recordingEnabled && consentRequired && self && !self.recordingConsent),
        selfConsented: !!self?.recordingConsent
      },
      counts: {
        pending: 0,
        raisedHands: 0,
        joined: self?.status === 'joined' ? 1 : 0,
        consentPending: 0,
        breakoutOpen: breakoutRooms.filter((room) => room.status === 'open').length
      },
      pendingParticipants: [],
      consentPendingParticipants: [],
      raisedHands: [],
      breakoutRooms,
      participants: self ? [self] : [],
      canManage: false
    };
  }
  return {
    self,
    recording: recordingState,
    counts: {
      pending: pending.length,
      raisedHands: raisedHands.length,
      joined: joined.length,
      consentPending: recordingEnabled ? consentPending.length : 0,
      breakoutOpen: breakoutRooms.filter((room) => room.status === 'open').length
    },
    pendingParticipants: pending,
    consentPendingParticipants: recordingEnabled ? consentPending : [],
    raisedHands,
    breakoutRooms,
    participants: participants.map(formatLiveParticipantForClient),
    canManage: true
  };
}

function canUserConsumeLiveSessionContent(user, session) {
  if (canUserManageSpecificLiveSession(user, session)) return true;
  const participant = getLiveSessionParticipant(session?.id, user?.id || user?.sub);
  const status = normalizeLiveParticipantStatus(participant?.status || '');
  if (!['approved', 'joined', 'left'].includes(status)) return false;
  const recording = getLiveSessionRecording(session?.id);
  if (Number(recording?.recording_enabled || 0) === 1 && Number(recording?.consent_required === 0 ? 0 : 1) === 1) {
    return normalizeLiveRecordingConsent(participant?.recording_consent);
  }
  return true;
}

const liveRecordingService = createLiveRecordingService({
  db,
  fileStorageService,
  nowIso,
  generateId,
  getSessionById: (sessionId) => db.prepare('SELECT * FROM live_sessions WHERE id = ?').get(String(sessionId || '').trim()) || null,
  getRecordingStateBySessionId: getLiveSessionRecording,
  upsertRecordingState: upsertLiveSessionRecording,
  getParticipant: getLiveSessionParticipant,
  canManageSession: canUserManageSpecificLiveSession,
  canViewSession: canUserViewLiveSession,
  isSuperAdminRole,
  userWorkspaceId,
  getNormalizedUserRole,
  defaultRetentionDays: 90
});

function validateLiveSessionTarget(user, { channelId, audience, existingSession = null, allowInvitedOnly = false } = {}) {
  const normalizedAudience = normalizeAudience(audience);
  if (isWorkspaceAdmin(user)) {
    return { ok: true, audience: normalizedAudience };
  }
  if (!isTeacherRole(user)) {
    return { ok: false, error: "Forbidden" };
  }
  if (allowInvitedOnly) {
    return {
      ok: true,
      audience: normalizedAudience,
      channelId: channelId || null,
      existingSession,
    };
  }
  if (!channelId) {
    return { ok: false, error: "Teachers can only create or edit sessions for allowed classes." };
  }
  if (!isUserInChannel(user.id, channelId)) {
    return { ok: false, error: "You can only manage live sessions for classes you belong to." };
  }
  return {
    ok: true,
    audience: normalizedAudience,
    channelId,
    existingSession,
  };
}

function validateInvitedLiveSessionUsers(workspaceId, invitedUserIds = [], options = {}) {
  const normalizedIds = normalizeLiveInvitedUserIds(invitedUserIds);
  if (!normalizedIds.length) {
    return { ok: false, error: "Please select at least one school member." };
  }
  const placeholders = normalizedIds.map(() => "?").join(",");
  const rows = db
    .prepare(`SELECT id, role FROM users WHERE workspace_id = ? AND id IN (${placeholders})`)
    .all(workspaceId, ...normalizedIds);
  const found = new Set(rows.map((row) => String(row.id || "")));
  const invalid = normalizedIds.filter((id) => !found.has(id));
  if (invalid.length) {
    return { ok: false, error: "Selected members must belong to this school." };
  }
  const allowedRoles = Array.isArray(options.allowedRoles)
    ? new Set(options.allowedRoles.map((role) => String(role || "").toLowerCase()))
    : null;
  if (allowedRoles && allowedRoles.size) {
    const disallowed = rows.filter((row) => !allowedRoles.has(getNormalizedUserRole(row)));
    if (disallowed.length) {
      return { ok: false, error: "Selected members do not match the allowed participant type." };
    }
  }
  return { ok: true, invitedUserIds: normalizedIds };
}

function formatDateOnly(date = new Date()) {
  const yyyy = date.getFullYear();
  const mm = String(date.getMonth() + 1).padStart(2, "0");
  const dd = String(date.getDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
}

function determineLiveScopeRange(scope = "today") {
  const normalized = String(scope || "today").toLowerCase();
  const base = new Date();
  const start = new Date(base.getFullYear(), base.getMonth(), base.getDate());
  let end = new Date(start);
  if (normalized === "week") {
    end.setDate(end.getDate() + 7);
  } else if (normalized === "all") {
    end = null;
  }
  return {
    scope: LIVE_SCOPE_VALUES.has(normalized) ? normalized : "today",
    start: formatDateOnly(start),
    end: end ? formatDateOnly(end) : null
  };
}

function normalizeAudience(value) {
  if (value === undefined || value === null || value === "") {
    return null;
  }
  const raw = String(value).toLowerCase();
  return LIVE_AUDIENCE_VALUES.has(raw) ? raw : null;
}

function formatLiveSessionScheduleLabel(session) {
  if (!session || !session.date) return "";
  const [year, month, day] = String(session.date || "").split("-");
  let dateLabel = session.date;
  if (year && month && day) {
    const parsed = new Date(Number(year), Number(month) - 1, Number(day));
    if (!Number.isNaN(parsed.getTime())) {
      dateLabel = parsed.toLocaleDateString("en-US", {
        weekday: "short",
        month: "short",
        day: "numeric"
      });
    }
  }
  const timeParts = [];
  if (session.start_time) timeParts.push(session.start_time);
  if (session.end_time) timeParts.push(session.end_time);
  const timeLabel = timeParts.join(" - ");
  return [dateLabel, timeLabel].filter(Boolean).join(" · ");
}

function getLiveAnnouncementState(session, variant = "scheduled") {
  const normalizedVariant = String(variant || "scheduled").toLowerCase();
  const derivedStatus = deriveLiveSessionStatus(session);
  if (normalizedVariant === "cancelled") {
    return {
      eventLabel: "LIVE SESSION",
      badgeText: "Canceled",
      badgeClass: "live-announcement-badge live-announcement-badge-canceled",
      ctaText: "Session canceled",
      ctaClass: "live-announcement-cta live-announcement-cta-disabled",
      ctaDisabled: true,
      noteText: "This live session was canceled.",
      wrapperClass: "live-announcement-card live-announcement-card-canceled",
    };
  }
  if (derivedStatus === "ended") {
    return {
      eventLabel: "LIVE SESSION",
      badgeText: "Expired",
      badgeClass: "live-announcement-badge live-announcement-badge-ended",
      ctaText: "Expired",
      ctaClass: "live-announcement-cta live-announcement-cta-disabled",
      ctaDisabled: true,
      noteText: "Session has expired.",
      wrapperClass: "live-announcement-card live-announcement-card-ended",
    };
  }
  if (derivedStatus === "live") {
    return {
      eventLabel: "LIVE NOW",
      badgeText: "Live now",
      badgeClass: "live-announcement-badge live-announcement-badge-live",
      ctaText: "Enter classroom",
      ctaClass: "live-announcement-cta live-announcement-cta-live",
      ctaDisabled: false,
      noteText: "",
      wrapperClass: "live-announcement-card live-announcement-card-live",
    };
  }
  if (normalizedVariant === "updated") {
    return {
      eventLabel: "SCHEDULED SESSION",
      badgeText: "Ready to join",
      badgeClass: "live-announcement-badge live-announcement-badge-ready",
      ctaText: "Join class",
      ctaClass: "live-announcement-cta live-announcement-cta-ready",
      ctaDisabled: false,
      noteText: "Session details were updated.",
      wrapperClass: "live-announcement-card live-announcement-card-updated",
    };
  }
  return {
    eventLabel: "SCHEDULED SESSION",
    badgeText: "Ready to join",
    badgeClass: "live-announcement-badge live-announcement-badge-ready",
    ctaText: "Join class",
    ctaClass: "live-announcement-cta live-announcement-cta-ready",
    ctaDisabled: false,
    noteText: "",
    wrapperClass: "live-announcement-card",
  };
}

function buildLiveAnnouncementActionHtml({ appPath, sessionId, channelId, ctaText, ctaClass, ctaDisabled }) {
  if (ctaDisabled || !appPath || !sessionId) {
    return `<span class="${ctaClass}" aria-disabled="true">${escapeHtml(ctaText)}</span>`;
  }
  return `<a class="${ctaClass}" href="${escapeHtml(appPath)}" target="_blank" rel="noopener noreferrer" data-live-session-id="${escapeHtml(sessionId)}" data-live-channel-id="${escapeHtml(channelId || "")}">${escapeHtml(ctaText)}</a>`;
}

function buildLiveSessionAnnouncementText(session, channel, variant = "scheduled") {
  if (!session) return "";
  const title = escapeHtml(session.title || "Live Class");
  const className = escapeHtml(channel?.name || "Live Class");
  const scheduleLabel = escapeHtml(formatLiveSessionScheduleLabel(session));
  const dateLabel = scheduleLabel;
  const notes = String(session.student_notes || "").trim();
  const appPath = buildLiveAppPath(session);
  const state = getLiveAnnouncementState(session, variant);
  const safeSessionId = escapeHtml(session.id || "");
  const safeChannelId = escapeHtml(session.channel_id || session.audience || "");
  const safeStatus = escapeHtml(session.status || "");
  const safeDate = escapeHtml(session.date || "");
  const safeStartTime = escapeHtml(session.start_time || "");
  const safeEndTime = escapeHtml(session.end_time || "");
  const safeAppPath = escapeHtml(appPath || "");
  const actionHtml = buildLiveAnnouncementActionHtml({
    appPath,
    sessionId: session.id,
    channelId: session.channel_id || session.audience || "",
    ctaText: state.ctaText,
    ctaClass: state.ctaClass,
    ctaDisabled: state.ctaDisabled,
  });
  const notesHtml = notes ? `<div class="live-announcement-note">${escapeHtml(notes)}</div>` : "";
  const stateNoteHtml = state.noteText ? `<div class="live-announcement-state-note">${escapeHtml(state.noteText)}</div>` : "";
  return `
    <section
      class="${state.wrapperClass}"
      aria-label="Live session event"
      data-live-session-id="${safeSessionId}"
      data-live-channel-id="${safeChannelId}"
      data-live-status="${safeStatus}"
      data-live-date="${safeDate}"
      data-live-start-time="${safeStartTime}"
      data-live-end-time="${safeEndTime}"
      data-live-app-path="${safeAppPath}"
    >
      <div class="live-announcement-accent" aria-hidden="true">
        <i class="fa-solid fa-video"></i>
      </div>
      <div class="live-announcement-body">
        <div class="live-announcement-label-row">
          <span class="live-announcement-label">${escapeHtml(state.eventLabel)}</span>
          <span class="${state.badgeClass}">${escapeHtml(state.badgeText)}</span>
        </div>
        <div class="live-announcement-title">${title}</div>
        <div class="live-announcement-meta">
          <span class="live-announcement-class">${className}</span>
          ${dateLabel ? `<span class="live-announcement-dot" aria-hidden="true"></span><span class="live-announcement-datetime">${dateLabel}</span>` : ""}
        </div>
        ${stateNoteHtml}
        ${notesHtml}
        <div class="live-announcement-actions">
          ${actionHtml}
        </div>
      </div>
    </section>
  `;
}

function autopostLiveSessionMessage(session, user, options = {}) {
  if (!session || !shouldAutopostLiveSession(session)) {
    return null;
  }
  const variant = String(options.variant || "scheduled").toLowerCase();
  const workspaceId = String(session.workspace_id || "default");
  const audience = String(session.audience || "").toLowerCase();
  const targetChannelIds = new Set();
  if (session.channel_id) {
    targetChannelIds.add(session.channel_id);
  }
  if (audience === "teachers" || audience === "general") {
    const teacherChannelId = ensureTeachersChannel(workspaceId);
    if (teacherChannelId) {
      targetChannelIds.add(teacherChannelId);
    }
  }
  if (audience === "general") {
    const classRows = db
      .prepare("SELECT id FROM channels WHERE workspace_id = ? AND lower(category) = 'classes'")
      .all(workspaceId);
    classRows.forEach((row) => {
      if (row?.id) {
        targetChannelIds.add(row.id);
      }
    });
  }
  if (!targetChannelIds.size) return null;

  const authorName =
    (user && (user.name || user.username || user.email)) || "Live Class";
  const initials = generateInitials(authorName) || "LC";
  const avatarUrl = resolveAvatarForAuthor(authorName, initials) || null;
  const language = normalizeLanguageCode(user?.native_language || user?.nativeLanguage || "en");
  const insertStmt = db.prepare(
    `INSERT INTO messages (id, channel_id, author, initials, avatar_url, time, text, alt, created_at, original_language)
     VALUES (@id, @channel_id, @author, @initials, @avatar_url, @time, @text, @alt, @created_at, @original_language)`
  );
  let postedMessage = null;
  targetChannelIds.forEach((channelId) => {
    const channel = db
      .prepare(
        "SELECT id, name, topic, category, workspace_id AS workspaceId FROM channels WHERE id = ?"
      )
      .get(channelId);
    if (!channel) return;
    const text = buildLiveSessionAnnouncementText(session, channel, variant);
    if (!text.trim()) return;
    const id = generateId("m");
    const time = timeHHMM();
    const createdAt = nowISOString();
    insertStmt.run({
      id,
      channel_id: channel.id,
      author: authorName,
      initials,
      avatar_url: avatarUrl || null,
      time,
      text,
      alt: 0,
      created_at: createdAt,
      original_language: language
    });
    const message = {
      id,
      author: authorName,
      initials,
      avatarUrl,
      time,
      text,
      originalLanguage: language,
      alt: false,
      createdAt,
      reactions: [],
      replies: []
    };
    broadcastEvent("channel_message_created", { channelId: channel.id, message });
    if (!postedMessage) {
      postedMessage = message;
    }
  });
  return postedMessage;
}

async function sendLiveSessionEmails({ workspaceId, channelId, session }) {
  if (!channelId) return { sent: 0, total: 0 };

  const settings =
    db.prepare('SELECT * FROM workspace_email_settings WHERE workspace_id = ?').get(workspaceId) || {};
  if (!settings.enabled) {
    return { sent: 0, total: 0 };
  }

  const workspaceRow =
    db.prepare('SELECT name, admin_email FROM workspaces WHERE id = ?').get(workspaceId) || {};
  const profileRow =
    db.prepare('SELECT * FROM workspace_profile WHERE workspace_id = ?').get(workspaceId) || {};
  const ownerEmail = String(getPlatformOwnerEmailSettings().owner_email || '').trim();
  const normalizedSettings = {
    ...settings,
    brand_school_name: String(settings.brand_school_name || workspaceRow.name || '').trim(),
    reply_to_email: String(settings.reply_to_email || workspaceRow.admin_email || ownerEmail || '').trim(),
    footer_text: String(settings.footer_text || '').trim()
  };
  const replyTo = normalizedSettings.reply_to_email;
  const fromName = buildAutomatedEmailSenderName(
    normalizedSettings.brand_school_name || workspaceRow.name || '',
    'live_session_invite'
  );
  const chan = db.prepare('SELECT name FROM channels WHERE id = ?').get(channelId);
  const className = chan?.name || 'Class';
  const prefix = normalizedSettings.subject_prefix ? `${normalizedSettings.subject_prefix} ` : '';
  const subject = `${prefix}Live class: ${session.title || 'Session'} (${className})`;
  const whenParts = [];
  if (session.date) whenParts.push(session.date);
  if (session.start_time) whenParts.push(session.start_time + (session.end_time ? `–${session.end_time}` : ''));
  const when = whenParts.join(' ');

  const brandName = normalizedSettings.brand_school_name || workspaceRow.name || '';
  const signatureHtml = buildEmailSignatureBlock({
    profileRow,
    workspaceRow,
    settings: normalizedSettings
  });
  const html = `
    <!DOCTYPE html>
    <html>
      <head>
        <meta charset="utf-8"/>
        <meta name="viewport" content="width=device-width,initial-scale=1.0"/>
        <title>${escapeHtml(subject)}</title>
      </head>
      <body style="margin:0;background:#fff;font-family:system-ui,-apple-system,Segoe UI,Roboto,Arial;color:#0f172a;">
        <div style="padding:18px;width:100%;box-sizing:border-box;">
          <div style="width:100%;margin:0">
            <div style="margin-bottom:16px;font-size:18px;font-weight:600;color:#1f2937">
              ${escapeHtml(brandLabel)}
            </div>
            <div style="border-radius:18px;background:#fff;box-shadow:0 20px 40px rgba(15,23,42,0.08);overflow:hidden;width:100%;box-sizing:border-box;">
              <div style="padding:18px">
                <div style="font-size:20px;font-weight:700;margin-bottom:8px;color:#0f172a">${escapeHtml(
                  session.title || 'Live class'
                )}</div>
                <div style="color:#475569;font-size:14px;margin-bottom:16px">
                  <strong style="font-weight:600;">Class:</strong> ${escapeHtml(className)} &middot;
                  <strong style="font-weight:600;">When:</strong> ${escapeHtml(when)}
                </div>
                <div>
                  <a href="${escapeHtml(session.meeting_url)}" style="display:inline-block;background:#2563eb;color:#fff;padding:12px 18px;border-radius:12px;text-decoration:none;font-weight:700;font-size:15px">
                    Join live class
                  </a>
                </div>
                ${session.meeting_pass ? `<div style="margin-top:10px;color:#0f172a"><strong>Password:</strong> ${escapeHtml(
                  session.meeting_pass
                )}</div>` : ''}
                ${session.student_notes ? `<div style="margin-top:10px;color:#0f172a"><strong>Notes:</strong> ${escapeHtml(
                  session.student_notes
                )}</div>` : ''}
              </div>
            </div>
            <div style="margin-top:18px">
              ${signatureHtml}
            </div>
            <div style="margin-top:16px;color:#94a3b8;font-size:12px">
              Sent by ${escapeHtml(brandLabel)}.
            </div>
          </div>
        </div>
      </body>
    </html>`;

  const textParts = [
    "Live class scheduled",
    `School: ${brandName || className}`,
    `Class: ${className}`,
    `When: ${when}`,
    `Link: ${session.meeting_url || ''}`
  ];
  if (session.meeting_pass) {
    textParts.push(`Password: ${session.meeting_pass}`);
  }
  if (session.student_notes) {
    textParts.push(`Notes: ${session.student_notes}`);
  }
  const text = textParts.join("\n");

  const memberRecipientRows = db
    .prepare(`
    SELECT DISTINCT trim(u.email) AS email
    FROM channel_members cm
    JOIN users u ON u.id = cm.user_id
    WHERE cm.channel_id = ?
      AND u.email IS NOT NULL
      AND trim(u.email) != ''
  `)
    .all(channelId || '')
    .map((r) => r.email)
    .filter((e) => e && e.includes('@'));
  const adminEmail = getWorkspaceAdminEmail(workspaceId);
  const recipients = Array.from(
    new Set([
      ...memberRecipientRows,
      ...(adminEmail && adminEmail.includes('@') ? [adminEmail] : [])
    ])
  );

  if (!recipients.length) {
    return { sent: 0, total: 0 };
  }

  const insertEvent = db.prepare(`
    INSERT INTO email_events (id, workspace_id, event_type, to_email, subject, status, provider, error_message, meta_json)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
  `);
  const metaJson = JSON.stringify({ channelId, sessionId: session.id });

  let sent = 0;
  for (const to of recipients) {
    const eventId = generateId('ee');
    try {
      await sendPlatformEmail({ to, subject, html, text, replyTo, fromName });
      insertEvent.run(
        eventId,
        workspaceId,
        'live_session_invite',
        to,
        subject,
        'sent',
        providerName,
        '',
        metaJson
      );
      sent++;
    } catch (err) {
      console.error('Email send failed:', to, err?.message || err);
      insertEvent.run(
        eventId,
        workspaceId,
        'live_session_invite',
        to,
        subject,
        'failed',
        providerName,
        String(err?.message || err),
        metaJson
      );
    }
  }

  return { sent, total: recipients.length };
}

app.delete('/api/messages/:messageId', async (req, res) => {
  const { messageId } = req.params;
  const { author } = req.body || {};
  const access = await assertMessageAccess(getTenantAccessUser(req), messageId, req);
  if (!access.ok) {
    if (access.status === 401) return res.status(401).json({ error: 'Unauthorized' });
    if (access.status === 404) return res.status(404).json({ error: 'Message not found' });
    return tenantForbidden(res);
  }
  const msg = await messageRepository.getMessageById(messageId);
  const user = getAuthedUser(req);
  const canBypass = isWorkspaceAdmin(user) || isTeacherRole(user);
  if (!canBypass && author && msg.author && msg.author !== author) {
    return res.status(403).json({ error: 'Only the author can delete this message' });
  }

  const { replyCount, reactionCount } = await messageRepository.getMessageInteractionCounts(messageId);
  if (!canBypass && (replyCount > 0 || (reactionCount || 0) > 0)) {
    return res.status(400).json({ error: 'Cannot delete a message with replies or reactions' });
  }

  await messageRepository.deleteMessage(messageId);
  if (isWorkspaceAdmin(user)) {
    audit('message.delete', req, {
      user,
      target: messageId,
      workspaceId: user.workspaceId || null,
      meta: { channelId: msg.channelId, author: msg.author, adminOverride: true }
    });
  }

  broadcastEvent('message_deleted', { channelId: msg.channelId, messageId });

  res.json({ ok: true, messageId, channelId: msg.channelId });
});

// create a reply in a thread
app.post('/api/channels/:channelId/messages/:messageId/replies', async (req, res) => {
  const { channelId, messageId } = req.params;
  const { author = 'You', initials = 'YOU', text, avatarUrl } = req.body || {};
  const channelAccess = await assertChannelAccess(getTenantAccessUser(req), channelId, req, { requireMembership: true });
  if (!channelAccess.ok) {
    if (channelAccess.status === 401) return res.status(401).json({ error: 'Unauthorized' });
    if (channelAccess.status === 404) return res.status(404).json({ error: 'Channel not found' });
    return tenantForbidden(res);
  }

  if (!text || !String(text).trim()) {
    return res.status(400).json({ error: 'Text is required' });
  }

  const parent = await messageRepository.getMessageParent(messageId, channelId);
  if (!parent) {
    return res.status(404).json({ error: 'Message not found' });
  }

  const id = generateId('r');
  const time = timeHHMM();
  const createdAt = nowIso();
  const fallbackAvatar = avatarUrl || resolveAvatarForAuthor(author, initials);

  const reply = await messageRepository.createReply({
    id,
    messageId,
    author,
    initials,
    avatarUrl: fallbackAvatar || null,
    time,
    text,
    createdAt
  });

  broadcastEvent('thread_reply_created', { channelId, messageId, reply });

  res.status(201).json(reply);
});

/* ---------- NEW: REACTIONS API ---------- */

app.post('/api/messages/:messageId/reactions', async (req, res) => {
  const { messageId } = req.params;
  const { emoji, userId: rawUserId } = req.body || {};
  if (!emoji) {
    return res.status(400).json({ error: 'emoji is required' });
  }

  const userId = String(rawUserId || 'anonymous').trim() || 'anonymous';

  const access = await assertMessageAccess(getTenantAccessUser(req), messageId, req);
  if (!access.ok) {
    if (access.status === 401) return res.status(401).json({ error: 'Unauthorized' });
    if (access.status === 404) return res.status(404).json({ error: 'Message not found' });
    return tenantForbidden(res);
  }

  const reactions = await messageRepository.toggleMessageReaction({ messageId, emoji, userId });
  const payload = { messageId, reactions };
  broadcastEvent('message_reactions_updated', payload);

  res.json(payload);
});

app.post('/api/replies/:replyId/reactions', async (req, res) => {
  const { replyId } = req.params;
  const { emoji, userId: rawUserId } = req.body || {};
  if (!emoji) {
    return res.status(400).json({ error: 'emoji is required' });
  }

  const userId = String(rawUserId || 'anonymous').trim() || 'anonymous';

  const replyAccess = resolveReplyAccessRow(replyId);
  if (!replyAccess) {
    return res.status(404).json({ error: 'Reply not found' });
  }
  const channelAccess = await assertChannelAccess(getTenantAccessUser(req), replyAccess.channelId, req, { requireMembership: true });
  if (!channelAccess.ok) {
    if (channelAccess.status === 401) return res.status(401).json({ error: 'Unauthorized' });
    return tenantForbidden(res);
  }

  const reactions = await messageRepository.toggleReplyReaction({ replyId, emoji, userId });
  const payload = { replyId, reactions };
  broadcastEvent('reply_reactions_updated', payload);

  res.json(payload);
});

/* ---------- Live Class Hub APIs ---------- */

app.get('/api/live-sessions', authRequired, (req, res) => {
  const scopeParam = String(req.query.scope || 'today');
  const { start, end } = determineLiveScopeRange(scopeParam);
  const user = req.auth || getAuthedUser(req);
  const workspaceId = userWorkspaceId(user);
  const conditions = ['ls.workspace_id = ?'];
  const params = [workspaceId];
  if (start) {
    conditions.push('ls.date >= ?');
    params.push(start);
  }
  if (end) {
    conditions.push('ls.date <= ?');
    params.push(end);
  }

  if (!user) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  if (isSuperAdminRole(user)) {
    void logTenantIsolationEvent(req, {
      workspaceId,
      targetType: 'liveSession',
      targetId: 'list',
      reason: 'super_admin_private_content_denied',
      type: 'security.super_admin_private_content_denied'
    });
    return tenantForbidden(res);
  }
  if (String(workspaceId || '').trim() !== String(user.workspaceId || user.workspace_id || '').trim()) {
    return tenantForbidden(res);
  }

  const rows = db
    .prepare(
      `SELECT ls.*, c.name AS channel_name
       FROM live_sessions ls
       LEFT JOIN channels c ON ls.channel_id = c.id
       WHERE ${conditions.join(' AND ')}
       ORDER BY ls.date ASC, ls.start_time ASC`
    )
    .all(...params);
  const visibleRows = isWorkspaceAdmin(user)
    ? rows
    : rows.filter((row) => canUserViewLiveSession(user, row));
  res.json(visibleRows.map((row) => ({
    ...hydrateLiveSession(row),
    liveControls: buildLiveSessionControlState(row, user)
  })));
});

app.post('/api/live-sessions', authRequired, express.json(), async (req, res) => {
  const user = req.auth || getAuthedUser(req);
  const canManage = canManageLiveSessions(user);
  const canStudentHost = canStudentHostLiveMeeting(user);
  if (!canManage && !canStudentHost) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  const payload = req.body || {};
  const {
    channel_id: channelId,
    channelId: channelIdAlt,
    title = 'Live Class',
    date,
    start_time: startTime,
    end_time: endTime,
    meeting_pass: meetingPass,
    student_notes: studentNotes,
    status = 'scheduled',
    autopost_mode: autopostMode = 'none',
    audience,
    invited_user_ids: invitedUserIdsRaw = [],
  } = payload;
  const notifyEmail = !!payload.notify_email;
  const normalizedAudience = normalizeAudience(audience);
  const workspaceId = userWorkspaceId(user);
  if (!workspaceId || isSuperAdminRole(user)) {
    return tenantForbidden(res);
  }
  const studentHostedMeeting = !canManage && canStudentHost;
  const normalizedInvitedUserIds = normalizeLiveInvitedUserIds(invitedUserIdsRaw);
  const invitedValidation = normalizedInvitedUserIds.length
    ? validateInvitedLiveSessionUsers(
        workspaceId,
        normalizedInvitedUserIds,
        studentHostedMeeting ? { allowedRoles: ['student'] } : {}
      )
    : null;
  const hasInvitedUsers = Boolean(invitedValidation?.ok);
  if (studentHostedMeeting && !hasInvitedUsers) {
    return res.status(403).json({ error: 'Students can only host invited group study meetings.' });
  }
  const requiresChannel = normalizedAudience === null && !hasInvitedUsers;
  const channelIdValue = channelId || channelIdAlt;
  if ((requiresChannel && !channelIdValue) || !date || !startTime || !endTime) {
    return res.status(400).json({ error: 'Missing required fields' });
  }
  const startAt = parseLiveSessionDateTime(date, startTime);
  const endAt = parseLiveSessionDateTime(date, endTime);
  if (!startAt || !endAt || endAt.getTime() <= startAt.getTime()) {
    return res.status(400).json({ error: 'End time must be after start time' });
  }
  const targetValidation = validateLiveSessionTarget(user, {
    channelId: requiresChannel ? channelIdValue : null,
    audience: normalizedAudience,
    allowInvitedOnly: hasInvitedUsers,
  });
  if (!targetValidation.ok) {
    return res.status(403).json({ error: targetValidation.error });
  }
  if (studentHostedMeeting && (requiresChannel || normalizedAudience)) {
    return res.status(403).json({ error: 'Students can only create invited group study meetings.' });
  }
  if (!requiresChannel && !normalizedAudience && !hasInvitedUsers) {
    return res.status(400).json({ error: 'Choose a class, audience, or invited members.' });
  }
  if (invitedValidation && !invitedValidation.ok) {
    return res.status(400).json({ error: invitedValidation.error });
  }
  let channelRow = null;
  if (requiresChannel) {
    channelRow = db
      .prepare('SELECT id, workspace_id FROM channels WHERE id = ?')
      .get(channelIdValue);
    if (!channelRow) {
      return res.status(404).json({ error: 'Channel not found' });
    }
    if (String(channelRow.workspace_id || '').trim() !== String(workspaceId || '').trim()) {
      return res.status(400).json({ error: 'Workspace mismatch' });
    }
  }
  const idempotencyKey = extractIdempotencyKey(req);
  if (idempotencyKey) {
    const existing = findExistingIdempotentLiveSession({
      workspaceId: (channelRow && channelRow.workspace_id) || workspaceId,
      channelId: requiresChannel ? channelIdValue : null,
      title: String(title || 'Live Class'),
      date,
      startTime,
      endTime,
      createdBy: user?.id || null
    });
    if (existing) {
      return res.status(200).json(hydrateLiveSession(existing));
    }
  }
  const sessionId = generateId('ls');
  const now = nowIso();
  const stmt = db.prepare(`
    INSERT INTO live_sessions
      (id, workspace_id, channel_id, title, date, start_time, end_time, meeting_url,
       meeting_pass, student_notes, status, autopost_mode, audience, created_by, created_at, updated_at, invited_user_ids)
    VALUES (@id, @workspace_id, @channel_id, @title, @date, @start_time, @end_time, @meeting_url,
            @meeting_pass, @student_notes, @status, @autopost_mode, @audience, @created_by, @created_at, @updated_at, @invited_user_ids)
  `);
  const record = {
    id: sessionId,
    workspace_id: (channelRow && channelRow.workspace_id) || workspaceId,
    channel_id: requiresChannel ? channelIdValue : null,
    title: String(title || 'Live Class'),
    date,
    start_time: startTime,
    end_time: endTime,
    meeting_url: '',
    meeting_pass: meetingPass || null,
    student_notes: studentNotes || null,
    status: String(status || 'scheduled'),
    autopost_mode: requiresChannel ? 'channel' : String(autopostMode || 'channel'),
    audience: normalizedAudience,
    created_by: user?.id || null,
    created_at: now,
    updated_at: now,
    invited_user_ids: hasInvitedUsers ? serializeLiveInvitedUserIds(invitedValidation.invitedUserIds) : ''
  };
  record.meeting_url = buildLiveMeetingUrl(record);
  stmt.run(record);
  ensureLiveSessionCalendar(record);
  autopostLiveSessionMessage(record, user);
  if (notifyEmail) {
    try {
      await sendLiveSessionEmails({
        workspaceId: record.workspace_id,
        channelId: record.channel_id,
        session: record
      });
    } catch (err) {
      console.error('Failed to send live session emails', err?.message || err);
    }
  }
  res.status(201).json(hydrateLiveSession(record));
});

app.patch('/api/live-sessions/:sessionId', (req, res) => {
  const user = getAuthedUser(req);
  if (!canManageLiveSessions(user)) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  const { sessionId } = req.params;
  const existing = db.prepare('SELECT * FROM live_sessions WHERE id = ?').get(sessionId);
  if (!existing) {
    return res.status(404).json({ error: 'Session not found' });
  }
  if (!canUserManageSpecificLiveSession(user, existing)) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  const payload = req.body || {};
  const updates = {};
  const fields = [
    'channel_id',
    'title',
    'date',
    'start_time',
    'end_time',
    'meeting_pass',
    'student_notes',
    'status',
    'autopost_mode',
    'audience',
    'invited_user_ids'
  ];
  fields.forEach((field) => {
    if (Object.prototype.hasOwnProperty.call(payload, field)) {
      if (field === 'audience') {
        updates.audience = normalizeAudience(payload.audience);
      } else if (field === 'invited_user_ids') {
        updates.invited_user_ids = serializeLiveInvitedUserIds(payload.invited_user_ids);
      } else {
        updates[field] = payload[field];
      }
    }
  });
  const audienceCandidate = Object.prototype.hasOwnProperty.call(updates, 'audience')
    ? updates.audience
    : existing.audience;
  const invitedCandidate = Object.prototype.hasOwnProperty.call(updates, 'invited_user_ids')
    ? updates.invited_user_ids
    : existing.invited_user_ids;
  const normalizedInvitedUserIds = normalizeLiveInvitedUserIds(invitedCandidate);
  const invitedValidation = normalizedInvitedUserIds.length
    ? validateInvitedLiveSessionUsers(existing.workspace_id, normalizedInvitedUserIds)
    : null;
  const hasInvitedUsers = Boolean(invitedValidation?.ok);
  if (invitedValidation && !invitedValidation.ok) {
    return res.status(400).json({ error: invitedValidation.error });
  }
  const normalizedAudience = normalizeAudience(audienceCandidate);
  if (normalizedAudience) {
    if (!isWorkspaceAdmin(user)) {
      return res.status(403).json({ error: 'Teachers can only edit sessions for allowed classes.' });
    }
    updates.channel_id = null;
    updates.audience = normalizedAudience;
    updates.invited_user_ids = '';
  } else if (hasInvitedUsers) {
    updates.channel_id = null;
    updates.audience = null;
    updates.invited_user_ids = serializeLiveInvitedUserIds(invitedValidation.invitedUserIds);
  } else {
    const finalChannelId = updates.channel_id ?? existing.channel_id;
    if (!finalChannelId) {
      return res.status(400).json({ error: 'Channel is required for class sessions' });
    }
    const targetValidation = validateLiveSessionTarget(user, {
      channelId: finalChannelId,
      existingSession: existing,
    });
    if (!targetValidation.ok) {
      return res.status(403).json({ error: targetValidation.error });
    }
    updates.channel_id = finalChannelId;
    delete updates.audience;
    updates.invited_user_ids = '';
    updates.autopost_mode = 'channel';
  }
  if (!Object.keys(updates).length) {
    return res.status(400).json({ error: 'No fields to update' });
  }
  const candidate = {
    ...existing,
    ...updates,
    audience: Object.prototype.hasOwnProperty.call(updates, 'audience') ? updates.audience : existing.audience,
  };
  const startAt = parseLiveSessionDateTime(candidate.date, candidate.start_time);
  const endAt = parseLiveSessionDateTime(candidate.date, candidate.end_time);
  if (!startAt || !endAt || endAt.getTime() <= startAt.getTime()) {
    return res.status(400).json({ error: 'End time must be after start time' });
  }
  updates.updated_at = nowIso();
  updates.meeting_url = buildLiveMeetingUrl(candidate);
  const setClause = Object.keys(updates)
    .map((key) => `${key} = @${key}`)
    .join(', ');
  const stmt = db.prepare(`UPDATE live_sessions SET ${setClause} WHERE id = @id`);
  stmt.run({ id: sessionId, ...updates });
  const updated = db.prepare('SELECT * FROM live_sessions WHERE id = ?').get(sessionId);
  autopostLiveSessionMessage(updated, user, { variant: "updated" });
  ensureLiveSessionCalendar(updated);
  res.json(hydrateLiveSession(updated));
});

